#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import finset fingroup. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam2004B2. Variable digit : finType. Hypothesis digit_nine : #|digit| = 9. Inductive oct_vertex := A | B | C | D | E | F | G | H | J. Definition oct_side1 := [:: A; J; E]. Definition oct_side2 := [:: B; J; F]. Definition oct_side3 := [:: C; J; G]. Definition oct_side4 := [:: D; J; H]. Definition oct_lines := [:: oct_side1; oct_side2; oct_side3; oct_side4]. Definition bijection := {ffun oct_vertex -> digit}. Definition linesums_eq (f : bijection) := \sum_(i <- oct_side1) f i = \sum_(i <- oct_side2) f i /\ \sum_(i <- oct_side1) f i = \sum_(i <- oct_side3) f i /\ \sum_(i <- oct_side1) f i = \sum_(i <- oct_side4) f i. Definition valid_assignments : nat := #|[set f : bijection | linesums_eq f]|. Theorem putnam_2004_b2 : valid_assignments > 0. Proof. Admitted. End
